import{_ as a,a0 as r,w as d,s as p,ao as n,I as t,x as o,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 FreeDOS 中设置和使用环境变量 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中设置和使用环境变量 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中设置和使用环境变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中设置和使用环境变量 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20210604 Set and use environment variables in FreeDOS","title":"在 FreeDOS 中设置和使用环境变量","tag":"202111","desc":""},"relativePath":"202111/20210604 Set and use environment variables in FreeDOS.md","filePath":"[post].md"}'),c={name:"202111/20210604 Set and use environment variables in FreeDOS.md"};function u(S,e,m,b,D,f){const s=r("Link");return d(),p("div",null,[e[22]||(e[22]=n('<h1 id="在-freedos-中设置和使用环境变量" tabindex="-1">在 FreeDOS 中设置和使用环境变量 <a class="header-anchor" href="#在-freedos-中设置和使用环境变量" aria-label="Permalink to “在 FreeDOS 中设置和使用环境变量”">​</a></h1><blockquote><p>环境变量几乎在每种命令行环境中都是很有帮助的，自然包括 FreeDOS 。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/18/152155twzasgwwrzsmmvs2.jpg" alt=""></p><p>几乎在每个命令行环境中的一个有用的功能是 <em>环境变量</em>。其中的一些变量允许你控制命令行的行为或功能，其它的变量仅允许你存储可能稍后需要的数据，在 FreeDOS 中也使用了环境变量。</p><h3 id="在-linux-上的变量" tabindex="-1">在 Linux 上的变量 <a class="header-anchor" href="#在-linux-上的变量" aria-label="Permalink to “在 Linux 上的变量”">​</a></h3>',5)),t("p",null,[e[1]||(e[1]=o("在 Linux 上，你可能已经熟悉其中的一些重要的环境变量。在 Linux 上的 ",-1)),l(s,{href:"https://opensource.com/article/19/8/using-variables-bash"},{default:i(()=>[...e[0]||(e[0]=[o("Bash",-1)])]),_:1}),e[2]||(e[2]=o(" shell 中，",-1)),e[3]||(e[3]=t("code",null,"PATH",-1)),e[4]||(e[4]=o(" 变量标示着 shell 可以在哪里找到程序和命令。例如，在我的 Linux 系统上，我的  ",-1)),e[5]||(e[5]=t("code",null,"PATH",-1)),e[6]||(e[6]=o(" 值如下：",-1))]),e[23]||(e[23]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash$ echo $PATH</span></span>
<span class="line"><span>/home/jhall/bin:/usr/lib64/ccache:/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin</span></span></code></pre></div><p>这意味着，当我输入一个像 <code>cat</code> 这样的命令的名称时，Bash 将会按顺序检查我在 <code>PATH</code> 变量中所列出的每个目录：</p><ol><li><code>/home/jhall/bin</code></li><li><code>/usr/lib64/ccache</code></li><li><code>/usr/local/bin</code></li><li><code>/usr/local/sbin</code></li><li><code>/usr/bin</code></li><li><code>/usr/sbin</code></li></ol><p>在我的实例中，<code>cat</code> 命令位于 <code>/usr/bin</code> 目录，因此，完整的路径是 <code>/usr/bin/cat</code> 。</p><p>为在 Linux 上设置一个环境变量，你可以输入一个变量的名称，接着输入一个等于符号（<code>=</code>），接着输入一个要存储在变量中的值。为了随后使用 Bash 引用这个值，你需要在变量的名称前输入一个美元符号（<code>$</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash$ var=Hello</span></span>
<span class="line"><span>bash$ echo $var</span></span>
<span class="line"><span>Hello</span></span></code></pre></div><h3 id="在-freedos-上的变量" tabindex="-1">在 FreeDOS 上的变量 <a class="header-anchor" href="#在-freedos-上的变量" aria-label="Permalink to “在 FreeDOS 上的变量”">​</a></h3><p>在 FreeDOS 上，环境变量提供一种类似的功能。一些变量控制 DOS 系统的行为，另一些变量用于存储一些临时值。</p><p>为在 FreeDOS 上设置一个环境变量，你需要使用 <code>SET</code> 关键字。FreeDOS 是 <em>不区分大小写的</em> ，因此你可以输入大写字母也可以使用小写字母。接下来，像你在 Linux 上一样设置变量，使用变量名称，一个等于符号（<code>=</code>），你想要存储的值。</p><p>不过，在 FreeDOS 中引用或 <em>扩展</em> 一个环境变量的值的方法，与你在 Linux 上所使用的方法是完全不同的。在 FreeDOS 中，你不能使用美元符号（<code>$</code>）来引用一个变量。你反而需要使用百分符号 （<code>%</code>）来包围变量的名称。</p><p><img src="https://opensource.com/sites/default/files/uploads/env-path.png" alt="Use % (not $) to reference a variable&#39;s value"></p><p>在名称前后使用百分符号是非常重要，因为这就是 FreeDOS 知悉变量名称在哪里开始和结束的方式。这是非常有用的，因为它会允许你引用一个变量的值，与此同时，它会立即附加（或预置）其它的文本到值中。让我通过设置一个新的名称为 <code>reply</code> 的值为 <code>yes</code> 的变量，然后在 “11” 之前和 “22” 之后引用这个值来演示这一点：</p><p><img src="https://opensource.com/sites/default/files/uploads/env-vars.png" alt="Set and reference an environment variable"></p><p>因为 FreeDOS 是不区分大小写的，所以你可以使用大写字母称或小写字母的变量名称以及 <code>SET</code> 关键字。不过，变量的值将使用你在命令行中所输入的字母。</p><p>最后，你可以看到当前在 FreeDOS 中定义的所有的环境变量。不使用任何参数的 <code>SET</code> 关键字将显示所有的变量，因此你可以一目了然：</p><p><img src="https://opensource.com/sites/default/files/uploads/env-set.png" alt="Show all variables at once with SET"></p><p>环境变量是一个有用的基本的命令行环境，同样适用于 FreeDOS 。你可以设置你自己的变量以满足你自己的需要，但是要仔细地更改 FreeDOS 使用的一些变量。这些变量会更改你正在运行的 FreeDOS 系统的行为：</p><ul><li><code>DOSDIR</code>：FreeDOS 安装目录的位置，通常是 <code>C:\\FDOS</code></li><li><code>COMSPEC</code>：FreeDOS 的 shell 的当前实例，通常是 <code>C:\\COMMAND.COM</code> 或 <code>%DOSDIR%\\BIN\\COMMAND.COM</code></li><li><code>LANG</code>：用户的首选语言</li><li><code>NLSPATH</code>：系统语言文件的位置，通常是 <code>%DOSDIR%\\NLS</code></li><li><code>TZ</code>：系统的时区</li><li><code>PATH</code>：一个目录列表，FreeDOS 可以在其中找到要运行的程序，例如 <code>%DOSDIR%\\BIN</code></li><li><code>HELPPATH</code>：系统文档文件的位置，通常是 <code>%DOSDIR%\\HELP</code></li><li><code>TEMP</code>：一个临时目录，FreeDOS 在其中存储来自每个命令的输出，如同它在命令行上的程序之间的 “管道” 数据</li><li><code>DIRCMD</code>：一个控制 <code>DIR</code> 命令如何显示文件和目录的变量，通常设置 <code>/OGNE</code> 来排序（<code>O</code>）内容，先通过分组（<code>G</code>）目录，接下来按照名称（<code>N</code>） 、扩展名（<code>E</code>）来排序条目</li></ul><p>如果你偶然间更改了任意的 FreeDOS 的 “内部” 变量，你可能会阻碍 FreeDOS 的一些部分的正常工作。在这种情况下，只需要简单地重新启动你的计算机，FreeDOS 将会按照系统默认值重新设置变量。</p><hr>`,20)),t("p",null,[e[8]||(e[8]=o("via: ",-1)),l(s,{href:"https://opensource.com/article/21/6/freedos-environment-variables"},{default:i(()=>[...e[7]||(e[7]=[o("https://opensource.com/article/21/6/freedos-environment-variables",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=o("作者：",-1)),l(s,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...e[9]||(e[9]=[o("Jim Hall",-1)])]),_:1}),e[14]||(e[14]=o(" 选题：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[10]||(e[10]=[o("lujun9972",-1)])]),_:1}),e[15]||(e[15]=o(" 译者：",-1)),l(s,{href:"https://github.com/robsean"},{default:i(()=>[...e[11]||(e[11]=[o("robsean",-1)])]),_:1}),e[16]||(e[16]=o(" 校对：",-1)),l(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=o("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[17]||(e[17]=[o("LCTT",-1)])]),_:1}),e[20]||(e[20]=o(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:i(()=>[...e[18]||(e[18]=[o("Linux中国",-1)])]),_:1}),e[21]||(e[21]=o(" 荣誉推出",-1))])])}const g=a(c,[["render",u]]);export{T as __pageData,g as default};
